pub fn add_all<'n, H>(&mut self, name: H, values: &mut Vec<Cow<'h, str>>) 
where 
    'n: 'h, 
    H: Into<Cow<'n, str>> 
{
    self.headers.insert(Uncased::new(name), values.drain(..).collect());
}

